from itertools import combinations
# nonzero vectors 1..31; 2D subspace nonzeros are {a,b,a^b}
subs=[]
seen=set()
for a,b in combinations(range(1,32),2):
    c=a^b
    if c==0: continue
    tri=tuple(sorted([a,b,c]))
    if tri not in seen:
        seen.add(tri); subs.append(set(tri))
print(len(subs)) # should Gaussian binomial [5 choose2]_2=(31*30)/(3*2)=155
# greedy find 6 disjoint triples (partial spread)
sol=[]; used=set()
for s in subs:
    if not (s&used):
        sol.append(s); used|=s
        if len(sol)==6: break
print(sol, len(sol), used)
# verify
# generate groups/cosets labels by smallest unassigned rep perhaps.
weeks=[]
for Snon in sol:
    S={0}|Snon
    # list cosets: starting from smallest uncovered point, coset sorted {rep xor s}
    covered=set(); cosets=[]
    for rep in range(32):
        if rep not in covered:
            cos=sorted([rep^s for s in S])
            cosets.append(cos); covered.update(cos)
    assert len(cosets)==8
    assign=[None]*32
    for gi,cos in enumerate(cosets):
        for p in cos: assign[p]=gi
    weeks.append(assign)
    print('S', sorted(Snon), 'cosets', cosets, 'assign', assign)
# verify group sizes and no repeated pair
pairs={}
for w,assign in enumerate(weeks):
    sizes=[assign.count(g) for g in range(8)]
    print('week', w, sizes)
    for g in range(8):
        players=[p for p,a in enumerate(assign) if a==g]
        for x,y in combinations(players,2):
            if (x,y) in pairs:
                print('repeat', (x,y), pairs[(x,y)], w)
                raise SystemExit
            pairs[(x,y)]=w
flat=[a for week in weeks for a in week]
print('flat length', len(flat))
print(flat)

from itertools import combinations
selected=[(1,2,3),(4,8,12),(5,10,15),(6,11,13),(7,16,23),(9,17,24)]
weeks=[]
for tri in selected:
    S={0,*tri}
    covered=set(); cosets=[]
    for rep in range(32):
        if rep not in covered:
            cos=sorted([rep^s for s in S])
            cosets.append(cos); covered.update(cos)
    assign=[None]*32
    for gi,cos in enumerate(cosets):
        for p in cos: assign[p]=gi
    weeks.append(assign)
    print('S',tri)
    print('cosets=',cosets)
    print('assign=',assign)
# verify
pairs={}
for w,assign in enumerate(weeks):
    assert all(assign.count(g)==4 for g in range(8))
    for g in range(8):
        players=[p for p,a in enumerate(assign) if a==g]
        for pair in combinations(players,2):
            if pair in pairs:
                print('repeat', pair,pairs[pair],w); raise SystemExit
            pairs[pair]=w
print('ok pairs', len(pairs)) # 6*8*C4,2=288 unique out C32,2=496
flat=[v for assign in weeks for v in assign]
print(len(flat))
print(','.join(map(str,flat)))
